<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {api,apiBlob,multipart,errorText} from '../api'
import {display} from '../quick/model'
import '../quick/quick.css'
import QuickReadiness from '../components/QuickReadiness.vue'
const route=useRoute(),router=useRouter()
const title=computed(()=>route.path==='/quick-history'?'实验历史':route.path==='/quick-lab'?'AI 实验室':'数据集中心')
const filters=ref<Record<string,string>>({}),data=ref<any>({items:[],total:0,result_count:0,page:1}),materials=ref<any[]>([]),busy=ref(false),error=ref(''),info=ref(''),preview=ref<any>(null),readiness=ref<any>(null),page=ref(1)
const selected=ref<Set<number>>(new Set())
const batchPreview=ref<any>(null),batchConfirmed=ref(false),batchFile=ref<HTMLInputElement>()
const q=()=>new URLSearchParams(Object.entries(filters.value).filter(([,v])=>v!=='')).toString()
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function load(reset=true){if(reset)page.value=1;await action(async()=>{data.value=(await api<any>('/quick/runs',{query:{...filters.value,page:page.value}})).data;preview.value=null;readiness.value=null;selected.value=new Set()})}
async function exportPreview(){await action(async()=>{preview.value=(await api<any>('/quick/dataset/preview',{query:filters.value})).data})}
async function check(){await action(async()=>{readiness.value=(await api<any>('/quick/dataset/readiness',{query:filters.value})).data})}
async function download(format:string){await action(async()=>{const {blob,filename}=await apiBlob(`/quick/dataset/download?format=${format}&${q()}`);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);info.value=`已生成 ${filename}。源与参数、双温区均已写入主表与明细表，详情见映射说明。`})}
function saveBlob(blob:Blob,filename:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function downloadTemplate(){await action(async()=>{const {blob,filename}=await apiBlob('/quick/batch/template');saveBlob(blob,filename);info.value=`已下载标准模板 ${filename}（33 列，含反应物C，两行表头）。`})}
async function uploadBatch(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await action(async()=>{const fd=new FormData();fd.append('file',file);batchPreview.value=(await multipart<any>('/quick/batch/preview',fd)).data;batchConfirmed.value=false;const p=batchPreview.value;info.value=`${file.name} 预览完成：识别「${p.sheet}」第 ${p.header_row} 行表头，匹配 ${p.matched_columns} 列；${p.row_count} 行可导入，${p.errors.length} 行有问题，${p.skipped.length} 行跳过。`});if(batchFile.value)batchFile.value.value=''}
async function confirmBatch(){await action(async()=>{const res=await api<any>('/quick/batch/confirm',{method:'POST',body:{rows:batchPreview.value.rows,expected_sha256:batchPreview.value.expected_sha256,confirm:true}});info.value=`已批量导入 ${res.data.count} 条实验记录。`;batchPreview.value=null;batchConfirmed.value=false;await load()})}
const materialName=(id:string)=>materials.value.find(m=>m.material_id===id)?.canonical_name||id
const reactantA=(r:any)=>r.program?.groups?.[0]?.steps?.[0]?.source_label||'—'
const reactantB=(r:any)=>r.program?.groups?.[0]?.steps?.[1]?.source_label||'—'
const reactantC=(r:any)=>r.program?.groups?.[0]?.steps?.[2]?.source_label||'—'
async function clear(){filters.value={};await load()}
async function next(d:number){page.value+=d;await load(false)}
const allSelected=computed(()=>data.value.items.length>0&&data.value.items.every((run:any)=>selected.value.has(run.run_id)))
function toggle(runId:number){const s=new Set(selected.value);s.has(runId)?s.delete(runId):s.add(runId);selected.value=s}
function toggleAll(){selected.value=allSelected.value?new Set():new Set(data.value.items.map((run:any)=>run.run_id))}
async function confirmAction(message:string){try{await ElMessageBox.confirm(message,'请确认',{type:'warning',confirmButtonText:'确认',cancelButtonText:'取消'});return true}catch{return false}}
async function removeRun(run:any){if(!await confirmAction(`永久删除「${run.experiment_date} · 第 ${run.daily_no} 次」？记录与结果将从数据库移除，不可撤销。`))return;await action(async()=>{await api(`/quick/runs/${run.run_id}`,{method:'DELETE'});info.value='已删除一条记录。';await load()})}
async function archiveRun(run:any){await action(async()=>{await api(`/quick/runs/${run.run_id}/archive`,{method:'POST'});info.value='已归档一条记录（可恢复）。';await load()})}
async function restoreRun(run:any){await action(async()=>{await api(`/quick/runs/${run.run_id}/restore`,{method:'POST'});info.value='已恢复一条记录。';await load()})}
async function batchArchive(){const ids=[...selected.value];if(!ids.length)return;await action(async()=>{await api('/quick/runs/batch-archive',{method:'POST',body:{run_ids:ids}});info.value=`已归档 ${ids.length} 条记录（可恢复）。`;await load()})}
async function batchDelete(){const ids=[...selected.value];if(!ids.length)return;if(!await confirmAction(`永久删除所选 ${ids.length} 条记录？此操作不可撤销。`))return;await action(async()=>{await api('/quick/runs/batch-delete',{method:'POST',body:{run_ids:ids}});info.value=`已删除 ${ids.length} 条记录。`;await load()})}
onMounted(async()=>{try{materials.value=(await api<any[]>('/quick/materials')).data}catch(e){error.value=errorText(e)}await load();if(route.path==='/quick-lab')await check()})
</script>
<template><div class="quick-page"><header class="quick-heading"><div><p class="eyebrow">ALE WORKBENCH / DATA</p><h1>{{title}}</h1><p>运行 × 结果行 · 来源、修订与连续关系可追溯</p></div><RouterLink to="/quick">新建实验快录</RouterLink></header>
 <div v-if="error" role="alert" class="quick-error">{{error}}<button :disabled="busy" @click="load()">重试读取</button></div><p role="status" aria-live="polite" class="quick-status">{{busy?'正在读取 / 生成文件…':info||`共 ${data.total} 次运行 · ${data.result_count} 条结果（两种计数分别统计）`}}</p>
 <section class="quick-card"><h2>筛选记录</h2><p class="quick-help">此处统计通过实验快录保存的运行与匿名结果。此前专业流程的样品、正式测量和原件可在专业模式查看。</p><div class="quick-filter"><label>材料<select aria-label="材料" v-model="filters.material_id"><option value="">所有材料</option><option v-for="m in materials" :key="m.material_id" :value="m.material_id">{{m.canonical_name}}</option></select></label><label>开始日期<input v-model="filters.date_from" type="date"></label><label>结束日期<input v-model="filters.date_to" type="date"></label><label>设备 / 腔体<input v-model="filters.equipment" placeholder="精确设备名"></label><label>数据真实性<select aria-label="数据真实性" v-model="filters.data_nature"><option value="">全部真实性</option><option value="real_experiment">真实实验</option><option value="synthetic">合成 / 软件验收</option><option value="unknown_legacy">遗留未知</option></select></label><label>质量状态<select aria-label="质量状态" v-model="filters.quality_status"><option value="">全部质量状态</option><option value="approved">已审核</option><option value="unreviewed">未审核</option><option value="excluded">排除</option></select></label><label>记录状态<select aria-label="记录状态" v-model="filters.archived"><option value="">未归档</option><option value="yes">已归档</option></select></label><label>有 EPC<select aria-label="有 EPC" v-model="filters.has_epc"><option value="">全部</option><option value="yes">有</option><option value="no">无</option></select></label><label>有均匀性<select aria-label="有均匀性" v-model="filters.has_uniformity"><option value="">全部</option><option value="yes">有</option><option value="no">无</option></select></label><label>Excel 补录<select aria-label="Excel 补录" v-model="filters.excel"><option value="">全部</option><option value="yes">已补录</option><option value="no">未补录</option></select></label></div><div class="quick-actions"><button class="primary" :disabled="busy" @click="load()">筛选</button><button :disabled="busy" @click="clear">清空筛选</button></div></section>
 <section class="quick-card"><h2>记录与结果</h2><p v-if="!data.items.length" class="empty">没有符合条件的记录。可清空筛选或创建实验快录。</p><template v-else><div class="quick-actions"><label class="check-line"><input type="checkbox" :checked="allSelected" @change="toggleAll">全选本页</label><button :disabled="busy||!selected.size" @click="batchArchive">归档所选{{selected.size?'（'+selected.size+'）':''}}</button><button :disabled="busy||!selected.size" @click="batchDelete">删除所选{{selected.size?'（'+selected.size+'）':''}}</button><span v-if="filters.archived==='yes'" class="quick-help">已归档记录可在此恢复；归档记录不参与导出与建模。</span></div><div class="quick-scroll" tabindex="0" aria-label="记录结果表，可横向滚动"><table class="quick-table"><thead><tr><th>日期 / 当日次序</th><th>材料 / 结果</th><th>有效 / 累计循环</th><th>前 → 后 (nm)</th><th>EPC (Å/cycle)</th><th>状态</th><th>操作</th></tr></thead><tbody><template v-for="run in data.items" :key="run.run_id"><tr v-for="(r,ri) in run.results" :key="r.result_id"><td>{{run.experiment_date}}<br>第 {{run.daily_no}} 次 · 第 {{run.stage_no}} 段</td><td>{{r.material_name||'未知'}} · {{r.alias}}</td><td>{{display(r.effective_cycles)}} / {{display(r.cumulative_cycles)}}</td><td>{{display(r.thickness_before_nm)}} → {{display(r.thickness_after_nm)}}</td><td>{{display(r.epc_a_per_cycle)}}</td><td>{{run.state==='draft'?'草稿':'已记录'}} / {{r.ingestion_status==='excel_confirmed'?'Excel已确认':r.ingestion_status==='manual_only'?'手记':'待补录'}}</td><td v-if="ri===0"><div class="quick-actions"><label class="check-line"><input type="checkbox" :checked="selected.has(run.run_id)" @change="toggle(run.run_id)">选择</label><RouterLink :to="'/quick?run='+run.run_id">查看</RouterLink><button v-if="!run.archived" @click="archiveRun(run)">归档</button><button v-else @click="restoreRun(run)">恢复</button><button @click="removeRun(run)">删除</button></div></td><td v-else></td></tr><tr v-if="!run.results.length"><td>{{run.experiment_date}}</td><td colspan="4">无结果行 · 参数草稿</td><td>{{run.state==='draft'?'草稿':'已记录'}}</td><td><div class="quick-actions"><label class="check-line"><input type="checkbox" :checked="selected.has(run.run_id)" @change="toggle(run.run_id)">选择</label><RouterLink :to="'/quick?run='+run.run_id">补录结果</RouterLink><button v-if="!run.archived" @click="archiveRun(run)">归档</button><button v-else @click="restoreRun(run)">恢复</button><button @click="removeRun(run)">删除</button></div></td></tr></template></tbody></table></div><div class="quick-actions"><button :disabled="busy||page===1" @click="next(-1)">上一页</button><span>第 {{page}} 页</span><button :disabled="busy||page*50>=data.total" @click="next(1)">下一页</button></div></template></section>
 <section class="quick-card"><h2>批量导入实验记录</h2><p class="quick-help">可直接上传你原来那份记录表：系统自动找到「日期 / 材料 / 反应物A…」所在表头行，列顺序、空格、全角符号、旧版 28 列与新 33 列都兼容，汇总行会自动跳过；也可以先下载标准模板再填写。上传后先逐行预览核对，再确认入库。材料必须已存在于你的材料目录，不会自动推断化学身份；未知值留空即可。重复实验ID 会提示在 Excel 中修改，系统不会自动改写。</p><div class="quick-actions"><button :disabled="busy" @click="downloadTemplate">下载标准模板</button><label class="grow">直接上传 xlsx（原有记录表或模板）<input ref="batchFile" type="file" accept=".xlsx,.xlsm" :disabled="busy" @change="uploadBatch"></label></div>
  <div v-if="batchPreview"><h3>预览 · {{batchPreview.row_count}} 行可导入 · {{batchPreview.errors.length}} 行有问题 · {{batchPreview.skipped.length}} 行跳过</h3><p class="quick-help">来源：{{batchPreview.sheet}} 第 {{batchPreview.header_row}} 行表头 · 匹配 {{batchPreview.matched_columns}} 列</p><p v-for="e in batchPreview.errors" :key="e" class="quick-warning">{{e}}</p><p v-for="s in batchPreview.skipped" :key="s" class="quick-help">{{s}}</p><div class="quick-scroll" tabindex="0" aria-label="批量导入预览表"><table class="quick-table"><thead><tr><th>行</th><th>日期</th><th>实验ID</th><th>材料</th><th>反应物A / B / C</th><th>温度(°C)</th><th>前 → 后 (nm)</th><th>质量</th></tr></thead><tbody><tr v-for="r in batchPreview.rows" :key="r._line"><td>{{r._line}}</td><td>{{r.experiment_date}}</td><td>{{r.external_experiment_id||'—'}}</td><td>{{materialName(r.material_id)}}</td><td>{{reactantA(r)}} / {{reactantB(r)}} / {{reactantC(r)}}</td><td>{{display(r.environment?.r1_temperature_c)}}</td><td>{{display(r.results?.[0]?.thickness_before_nm)}} → {{display(r.results?.[0]?.thickness_after_nm)}}</td><td>{{r.results?.[0]?.quality_status}}</td></tr></tbody></table></div><label class="check-line"><input v-model="batchConfirmed" type="checkbox">我已逐行核对字段、单位与材料，确认导入</label><div class="quick-actions"><button class="primary" :disabled="busy||!batchConfirmed||!batchPreview.row_count||batchPreview.errors.length" @click="confirmBatch">确认入库</button><button :disabled="busy" @click="batchPreview=null;batchConfirmed=false">取消</button></div></div></section>
 <section class="quick-card"><h2>导出与数据体检</h2><p>筛选条件应用于完整导出。结果为空时仍可下载含表头及清单的文件。主表 33 列（含反应物A/B/C 三套参数）按已确认映射写出；第 4 列及以后的源、R2 与外部标识在记录明细 / 源步骤明细 / 结果明细中保留。</p><div class="quick-actions"><button :disabled="busy" @click="exportPreview">预览导出</button><button :disabled="busy" @click="download('xlsx')">导出 33 列 XLSX</button><button :disabled="busy" @click="download('json')">导出完整 JSON</button><button :disabled="busy" @click="download('wide')">导出建模宽表</button><button class="primary" :disabled="busy" @click="check">数据体检</button></div><div v-if="preview"><h3>导出映射预览 · {{preview.run_count}} 次运行 / {{preview.result_count}} 条结果</h3><p v-for="warning in preview.warnings" :key="warning" class="quick-warning">{{warning}}</p><pre tabindex="0">{{JSON.stringify(preview,null,2)}}</pre></div><div v-if="readiness"><QuickReadiness :report="readiness"/><div class="quick-actions"><button :disabled="busy" @click="download('readiness_json')">下载 dataset_readiness.json</button><button :disabled="busy" @click="download('readiness_html')">下载可读 HTML 报告</button></div></div></section>
 <p v-if="route.path==='/quick-lab'" class="quick-help">前向预测、反向寻优、主动学习需先确认通道映射与可训练数据。当前接口提供真实数据体检；未接入设备、未训练或伪造预测。</p>
</div></template>
